import{_ as r,o as a,c as e,ag as o}from"./chunks/framework.Aev9KvMf.js";const b=JSON.parse('{"title":"公积金查询 · 余额、提取与继承","description":"住房公积金官方查询教程：全国住房公积金小程序查余额缴存、依法提取情形、身故后继承人提取路线，12329 热线。","frontmatter":{"title":"公积金查询 · 余额、提取与继承","issuer":"住房和城乡建设部（全国住房公积金服务）","source_tier":"一级来源","version":"—","published":"—","source_url":"https://www.mohurd.gov.cn/","status":"现行服务","tags":["官方查询","公积金","提取","继承","家庭财务"],"type":"查询页","reviewed":false,"description":"住房公积金官方查询教程：全国住房公积金小程序查余额缴存、依法提取情形、身故后继承人提取路线，12329 热线。"},"headers":[],"relativePath":"query/housing-fund.md","filePath":"query/housing-fund.md"}'),d={name:"query/housing-fund.md"};function n(h,t,s,l,i,u){return a(),e("div",null,[...t[0]||(t[0]=[o('<h1 id="公积金查询-·-余额、提取与继承" tabindex="-1">公积金查询 · 余额、提取与继承 <a class="header-anchor" href="#公积金查询-·-余额、提取与继承" aria-label="Permalink to &quot;公积金查询 · 余额、提取与继承&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">待核验</p><p>本页由 AI 会话信息整理；公积金提取细则<strong>各地不同</strong>，以当地公积金中心规定为准。</p></div><blockquote><p><strong>官方入口</strong>：微信/支付宝搜索&quot;<strong>全国住房公积金</strong>&quot;小程序（住建部指导）；各地公积金中心官网/APP；热线 <strong>12329</strong>。· 一级来源</p></blockquote><h2 id="速览卡" tabindex="-1">速览卡 <a class="header-anchor" href="#速览卡" aria-label="Permalink to &quot;速览卡&quot;">​</a></h2><p>公积金不只是买房才用得上：<strong>租房、退休、大病等情形可依法提取</strong>；职工身故后，账户余额由<strong>继承人提取</strong>（《住房公积金管理条例》，待核验）——这是很多家庭漏掉的一笔钱。</p><h2 id="_30-秒查询步骤-待核验" tabindex="-1">30 秒查询步骤（待核验） <a class="header-anchor" href="#_30-秒查询步骤-待核验" aria-label="Permalink to &quot;30 秒查询步骤（待核验）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>步骤</th><th>怎么做</th></tr></thead><tbody><tr><td>1</td><td>打开&quot;全国住房公积金&quot;小程序，实名登录</td></tr><tr><td>2</td><td><strong>查余额与缴存记录</strong>：账户明细一目了然</td></tr><tr><td>3</td><td><strong>提取</strong>：按情形走当地中心线上/线下流程（购房、租房、退休等）</td></tr><tr><td>4</td><td><strong>身故继承提取</strong>：继承人凭死亡证明+关系证明，到当地公积金中心办理</td></tr></tbody></table><h2 id="结果怎么读" tabindex="-1">结果怎么读 <a class="header-anchor" href="#结果怎么读" aria-label="Permalink to &quot;结果怎么读&quot;">​</a></h2><table tabindex="0"><thead><tr><th>情形</th><th>说明</th></tr></thead><tbody><tr><td>在职正常缴存</td><td>可查缴存单位与月缴存额（<a href="https://www.mohurd.gov.cn/" target="_blank" rel="noreferrer">小程序</a>）</td></tr><tr><td>退休</td><td>可全额销户提取</td></tr><tr><td>身故</td><td>继承人依法提取余额；多人继承需协商或公证——细节问 12329</td></tr></tbody></table><h2 id="避坑要点" tabindex="-1">避坑要点 <a class="header-anchor" href="#避坑要点" aria-label="Permalink to &quot;避坑要点&quot;">​</a></h2><table tabindex="0"><thead><tr><th>骗局话术</th><th>官方依据</th></tr></thead><tbody><tr><td>&quot;公积金代提代办，收手续费&quot;</td><td>符合条件的提取本人即可办、<strong>不收任何手续费</strong>，中介多为诈骗</td></tr><tr><td>&quot;离职就能立刻全额提现&quot;</td><td>异地转移接续与提取规则各地不同，先问 12329 再签任何协议</td></tr></tbody></table><h2 id="相关页面" tabindex="-1">相关页面 <a class="header-anchor" href="#相关页面" aria-label="Permalink to &quot;相关页面&quot;">​</a></h2><ul><li>政策解读：<a href="/SageRelay/social/pension-after-death.html">养老金身故后怎么办</a></li><li>热线：12329（公积金）/ 12333（社保）</li></ul><h2 id="溯源" tabindex="-1">溯源 <a class="header-anchor" href="#溯源" aria-label="Permalink to &quot;溯源&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>内容</th></tr></thead><tbody><tr><td>法规</td><td>《住房公积金管理条例》（提取与继承条款，待核验）</td></tr><tr><td>入口</td><td>&quot;全国住房公积金&quot;小程序 · <a href="https://www.mohurd.gov.cn/" target="_blank" rel="noreferrer">住建部官网</a> · 12329</td></tr></tbody></table>',15)])])}const g=r(d,[["render",n]]);export{b as __pageData,g as default};
